"""프로그램 6쪽. 내용은 연구소 블로그 글(2024 ~ 2026)을 정리한 것 — 없는 숫자 · 효과를 지어 넣지 않는다."""
from kit import *
import sym

def duo(left, right, cls=""): return f'<div class="duo{" " + cls if cls else ""}"><div>{left}</div><div class="rv">{right}</div></div>'
def intro(kick, title, body, pic, alt, cap="", rows=None):
    return sec(duo(f'{tag(kick)}<h2>{title}</h2><div class="prose lead-p">{body}</div>{kv(rows, "slim") if rows else ""}', figure(pic, alt, cap, sizes="(max-width: 760px) 100vw, 600px")))
def who(title, items, lead=""): return sec(head("이런 모습이 보인다면", title, lead) + checks(items), "sec-soft")
HOSP = note("<b>알아 두세요.</b> 이 쪽의 내용은 일반적인 안내이며 진단이 아닙니다. 진단은 의료기관에서 받고, 연구소에서는 상담과 평가를 거쳐 아이에게 맞는 수업을 정합니다.")
VOUCH = ("바우처", f'발달재활서비스 · 치료지원(굳센카드) <a class="tlink" href="{href("voucher")}">금액 보기</a>')

def speech():
    ms = [("12개월", "첫 낱말", "엄마 · 아빠, 맘마 · 까까 · 물처럼 익숙한 사람과 사물을 말합니다."), ("18 ~ 24개월", "어휘 폭발기", "약 50개의 낱말을 쓰고, 두 낱말을 이어 말하기 시작합니다."), ("24개월", "두 낱말 문장", "270 ~ 500개 낱말. '더 · 또 · 많이' 같은 말이 늘어납니다."), ("36개월", "문장으로", "이때도 낱말 · 문장이 부족하다면 평가를 받아 보시길 권합니다.")]
    ruler = '<ol class="ruler">' + "".join(f'<li class="rv"><b>{a}</b><h3>{t}</h3><p>{d}</p></li>' for a, t, d in ms) + "</ol>"
    body = intro("말 · 언어 — 언어치료", "<span class=\"nb\">말이 늦는 것 같다면,</span> <span class=\"nb\">먼저 지금을 확인합니다</span>",
        "<p>또래보다 말이 늦은 것 같아 걱정되어 문의하시는 분이 많습니다. 연구소에서는 언어발달 평가와 초기 상담으로 아이의 지금 언어 발달 상태를 먼저 확인하고, 그에 맞춰 수업을 시작합니다.</p>",
        "g-speech-a", "언어치료 책상 — 선생님이 아이 앞에 사과 · 바나나 · 강아지 그림 카드를 펼쳐 보이는 모습", "", [("대상", "말이 늦거나 의사소통이 어려운 영유아 · 아동 · 청소년"), ("담당", "언어재활사 1급 3명"), VOUCH])
    body += who("<span class=\"nb\">이럴 때</span> <span class=\"nb\">상담을 권합니다</span>", ["또래보다 말이 늦다", "의사소통이 어렵거나 표현이 제한적이다", "만 2세가 되어도 또래에 비해 말이 늦다", "만 3세가 되어도 문장으로 말하지 않는다", "글자는 아는데 읽기를 힘들어한다", "말 대신 울음이나 떼로 요구를 표현한다"])
    body += sec(head("언어 발달 이정표", "<span class=\"nb\">보통 이 무렵에</span> <span class=\"nb\">이런 말이 나옵니다</span>", "아이마다 속도가 다릅니다. 아래는 일반적인 흐름이며, 한두 가지가 늦다고 해서 곧 지연이라는 뜻은 아닙니다.") + ruler + HOSP)
    body += sec(head("연구소에서 하는 것", "<span class=\"nb\">아이의 수준에 맞춰</span> <span class=\"nb\">네 가지를 다룹니다</span>") + figure("g-speech-b", "아이가 공 그림 카드를 손가락으로 가리키고 선생님이 지켜보는 모습", "", "wide") + cards([
        ("의사소통 능력", "원하는 것을 전하고 주고받는 경험을 늘립니다."), ("어휘와 문장", "낱말을 넓히고 문장으로 이어 말하도록 돕습니다."), ("발음 · 조음", "소리를 정확하게 내도록 지도합니다."), ("그림으로 말하기", f'말이 아직 어려운 아이는 그림 카드(PECS)나 의사소통 판(AAC)으로 먼저 시작합니다. <a class="tlink" href="{href("aac")}">자세히</a>')]), "sec-soft")
    body += sec(duo(f'{tag("읽기가 힘든 아이")}<h2><span class="nb">글자는 아는데</span> <span class="nb">읽기를 힘들어한다면</span></h2><div class="prose"><p>읽기의 어려움은 게으르거나 공부를 안 해서가 아니라, 글자와 소리와 뜻을 빠르게 잇는 과정의 어려움일 수 있습니다. 연구소에는 한국난독증협회 문해교육전문가 과정을 마친 언어재활사가 있습니다.</p></div>{btn("읽기 · 학습 안내 보기", href("learning"), "line")}',
        f'<div class="callout"><h3>이런 모습이 이어진다면</h3>{dots(["글자를 자주 바꿔 읽는다 (바다 → 다바)", "한 글자씩 끊어 읽고 속도가 매우 느리다", "받아쓰기를 매우 어려워한다", "읽기를 매우 싫어한다", "읽은 내용을 잘 이해하지 못한다"])}</div>'))
    body += call_band()
    return subpage("speech", "<span class=\"nb\">말 · 언어</span>", "또래보다 말이 늦거나, 하고 싶은 말을 전하기 어려워하는 아이를 위한 언어치료입니다.", body, kicker="언어치료", shape="a")

def aac():
    stages = [("그림을 건네기", "원하는 물건의 그림을 상대방에게 건넵니다."), ("다가가서 건네기", "거리를 이동해 상대방에게 카드를 가져갑니다."), ("그림 고르기", "여러 그림 가운데 원하는 것을 고릅니다."), ("문장 만들기", "\"~ 주세요\" 문장 띠를 만듭니다."), ("질문에 대답하기", "\"뭐 먹을래?\"에 그림으로 답합니다."), ("스스로 말 걸기", "묻지 않아도 문장으로 표현합니다.")]
    strip = '<div class="strip rv" aria-label="문장 띠 예시">' + sym.card("me", "나는") + sym.card("cookie", "쿠키") + sym.card("give", "주세요") + '<span class="strip-say">"아, 쿠키 먹고 싶구나!"</span></div>'
    body = intro("그림으로 말하기 — PECS · AAC", "<span class=\"nb\">말 대신 그림으로,</span> <span class=\"nb\">먼저 뜻을 전합니다</span>",
        "<p><b>보완대체의사소통(AAC)</b>은 말로 표현하기 어려운 사람이 그림 상징이나 글자, 음성 기기 같은 다른 방법으로 의사소통하도록 돕는 체계입니다. 그 가운데 <b>PECS(그림교환의사소통체계)</b>는 그림 카드를 상대방에게 건네며 뜻을 전하는 방법입니다.</p><p>그림은 말을 대신하려는 것이 아니라 말을 배우도록 돕는 도구입니다. 아이는 \"내가 표현하면 원하는 것이 이루어진다\"는 경험을 하게 됩니다.</p>",
        "g-aac-a", "아이의 손이 과자 그림 카드를 선생님의 손바닥 위에 건네는 모습", "", [("대상", "말이 거의 없거나 요구 표현이 어려운 아동 · 청소년 · 성인"), ("담당", "PECS Level 1 · 2 연수, AAC 전문가 심화 과정을 마친 언어재활사"), ("방식", "개별 수업 + 시기별 소그룹 활동")])
    body += who("<span class=\"nb\">이런 아이에게</span> <span class=\"nb\">씁니다</span>", ["말이 거의 없다", "요구를 말로 표현하기 어렵다", "울거나 소리를 지르거나 떼를 쓰는 것으로 표현한다", "같은 말을 되풀이할 뿐 주고받는 말이 어렵다", "자폐스펙트럼 · 발달지연으로 언어 사용이 제한적이다", "눈으로 보는 자료에 더 잘 반응한다"])
    body += sec(head("PECS 여섯 단계", "<span class=\"nb\">그림 한 장에서</span> <span class=\"nb\">문장까지, 단계로</span>", "단계를 차례로 밟으며 의사소통이 넓어집니다. 그림 → 낱말 → 문장으로 이어집니다.") + steps(stages, "steps-6") + f'<div class="strip-row">{strip}{figure("pecs-book", "그림 카드가 붙어 있는 의사소통 책과 문장 띠", "연구소 수업에 쓰는 그림 카드 책", "small")}</div>')
    body += sec(head("핵심어휘와 부수어휘", "<span class=\"nb\">어디서나 쓰는 말부터</span> <span class=\"nb\">가르칩니다</span>") + cards([
        ("핵심어휘", "주세요 · 먹어요 · 맛있어요처럼 어느 상황에서나 되풀이해 쓰는 말입니다. \"주세요\" 하나로 물 · 공 · 색연필을 달라고 할 수 있습니다."),
        ("부수어휘", "감자튀김 · 케첩 · 에어프라이어처럼 그 활동에서만 쓰는 말입니다. 피자를 만들면 피자 · 치즈 · 오븐으로 바뀝니다."),
        ("활동 속에서", "핵심어휘를 중심으로 가르치고 활동에 따라 부수어휘를 더합니다. 교재가 아니라 실제 생활에서 쓸 때 뜻이 살아납니다.")], "box"), "sec-soft")
    acts = [("순서를 미리 봅니다", "만들어요 → 넣어요 → 기다려요 → 꺼내요 → 접시에 담아요. 다음에 무엇을 할지 그림으로 먼저 알려 줍니다."), ("이름을 말합니다", "\"이거 뭐야?\"라고 물으면 판에서 감자튀김 · 케첩을 가리켜 답합니다."), ("기다립니다", "'기다려요' 그림을 보며 기다립니다. 말로 설명하기 어려운 개념을 눈으로 보여 줍니다."), ("달라고 합니다", "필요한 물건을 일부러 멀리 두고, \"접시 주세요 · 포크 주세요\"로 요청하게 합니다."), ("안전을 배웁니다", "에어프라이어 옆에 '뜨거워요' 그림을 두어 뜻을 되풀이해 경험합니다.")]
    body += sec(duo(figure("aac-board", "에어프라이어 옆에 놓인 의사소통 판", "감자튀김 만들기 활동의 의사소통 판 (2026년 6월)", sizes="(max-width: 760px) 100vw, 600px"), f'{tag("활동 기록")}<h2><span class="nb">감자튀김을 만들며</span> <span class="nb">배운 것들</span></h2><ol class="nums">' + "".join(f"<li><b>{t}</b><span>{d}</span></li>" for t, d in acts) + "</ol>", "rev") )
    body += sec(duo(f'{tag("활동 기록")}<h2><span class="nb">그림 카드를 들고</span> <span class="nb">마트에 갑니다</span></h2><div class="prose"><p>그림으로 오늘 일정을 미리 알려 주고, 마트에서 \'팝콘\' \'사고 싶어요\' 카드로 원하는 것을 삽니다. 함께 가 보면 아이가 무엇을 좋아하는지 새로 알게 됩니다.</p><p>말로는 색깔을 정확히 표현하지 못하던 학생이 그림 카드로는 원하는 색깔의 초콜릿을 정확하게 요구했습니다.</p></div>{note("방학에는 발달장애 청소년 · 성인 4 ~ 5명 소그룹으로 만들기 · 지역사회 활동을 하는 특별활동을 열기도 합니다. 모집 여부는 전화로 확인해 주세요.")}',
        figure("pecs-color", "책상 위의 그림 카드 책과 색깔별 초콜릿", "색깔을 그림 카드로 요구하는 수업", sizes="(max-width: 760px) 100vw, 600px")), "sec-soft")
    body += sec(note("PECS®는 Pyramid Educational Consultants 의 등록 상표입니다. 이 쪽의 그림은 설명을 위해 새로 그린 것이며 특정 상징 체계의 그림이 아닙니다.", "plain"), "sec-thin")
    body += call_band()
    return subpage("aac", "<span class=\"nb\">그림으로 말하기</span>", "말로 표현하기 어려운 아이가 그림 카드와 의사소통 판으로 뜻을 전하도록 돕습니다.", body, kicker="PECS · AAC", shape="b")

def learning():
    body = intro("읽기 · 학습 — 인지치료", "<span class=\"nb\">못하는 것이 아니라,</span> <span class=\"nb\">배우는 방식이 다릅니다</span>",
        "<p>덧셈을 배웠는데 금방 잊어버리고, 문제를 이해하는 데 오래 걸리고, 글자는 아는데 읽기를 힘들어하는 아이가 있습니다. 단순히 공부를 못해서가 아니라 정보를 처리하는 방식의 차이 때문일 수 있습니다.</p><p>인지치료는 특수학교 교사로 일했던 원장과 부원장이 맡습니다. 두 분 모두 30년 넘게 특수학생과 학습에 어려움이 있는 아이들을 가르쳐 왔습니다.</p>",
        "g-learn-a", "책상 위의 그림 카드를 아이와 선생님이 함께 고르는 모습", "", [("대상", "읽기 · 쓰기 · 수학이나 수업 진도를 따라가기 어려운 아동 · 청소년"), ("담당", "원장 · 부원장 (특수학교 정교사, 인지행동지도사 1급)"), VOUCH])
    body += who("<span class=\"nb\">이런 어려움이</span> <span class=\"nb\">이어진다면</span>", ["글자를 자주 바꿔 읽거나 한 글자씩 끊어 읽는다", "받아쓰기를 매우 어려워한다", "덧셈을 배워도 금방 잊어버린다", "숫자는 아는데 문제를 풀면 계속 틀린다", "문장으로 된 문제를 이해하는 데 오래 걸린다", "집중이 어렵고 학습 기초가 부족하다"])
    body += sec(head("수학이 어려운 까닭", "<span class=\"nb\">숫자를 아는 것만으로는</span> <span class=\"nb\">풀리지 않습니다</span>", "경계선 지능은 지능지수가 약 70 ~ 85 사이에 있는 경우를 말합니다. 지적장애는 아니지만 일반적인 학습을 따라가기 어려울 수 있고, 특히 수학 · 읽기 이해 · 문제 해결에서 어려움이 나타나곤 합니다.") + cards([
        ("작업기억", "23 + 18 을 풀려면 3 + 8, 받아올림, 십의 자리 계산을 동시에 기억해야 합니다. 작업기억이 약하면 중간 과정을 놓칩니다."),
        ("개념 이해", "자리값 · 분수 · 나눗셈처럼 눈에 보이지 않는 개념은 이해하기 어렵습니다."),
        ("문제 이해", "\"사과 5개가 있고 3개를 더 샀습니다\"에서 무엇을 구하고 어떤 계산을 할지 파악하는 과정이 어려울 수 있습니다.")], "box"))
    body += sec(head("지도 원칙", "<span class=\"nb\">연구소에서는</span> <span class=\"nb\">이렇게 가르칩니다</span>") + steps([
        ("구체적인 경험부터", "숫자보다 블록 · 구슬 · 과자 같은 실제 물건으로, 눈으로 보고 손으로 만지며 수 개념을 배웁니다."),
        ("한 번에 하나씩", "한 번에 하나의 개념을, 충분히 되풀이하며, 단계를 나누어 배웁니다."),
        ("눈에 보이게", "수직선 · 그림 · 도식 · 색깔 구분 같은 시각 자료를 씁니다."),
        ("성공 경험을 많이", "쉬운 문제부터 시작해 작은 성공을 쌓고, 긍정적으로 되돌려 줍니다.")]) + figure("g-learn-b", "아이가 나무 주판의 색 구슬을 하나씩 옮기는 모습", "", "wide"), "sec-soft")
    body += sec(duo(f'{tag("읽기 지도")}<h2><span class="nb">읽기의 어려움도</span> <span class="nb">도움을 받을 수 있습니다</span></h2><div class="prose"><p>읽기에 어려움이 있다고 해서 배울 수 없는 것은 아닙니다. 아이의 특성에 맞춘 체계적인 읽기 지도가 중요합니다. 읽기의 어려움은 보통 본격적으로 읽기를 배우는 초등학교 1 ~ 2학년 무렵에 발견되는 경우가 많습니다.</p></div>',
        f'<div class="callout"><h3>읽기 지도에서 다루는 것</h3>{dots(["음운 인식 훈련", "글자와 소리를 잇는 훈련", "반복 읽기", "단계적인 읽기 훈련"])}</div>'))
    body += sec(head("집에서 함께", "<span class=\"nb\">생활 속 수 경험이</span> <span class=\"nb\">공부가 됩니다</span>") + cards([
        ("과일 나누기", "\"사과 4개를 두 명이 나눠 먹으면 몇 개씩일까?\""), ("간식 세기", "\"쿠키가 몇 개 남았지?\""), ("장보기", "\"사과 2개 더 담아 볼까?\"")]) + HOSP, "sec-soft")
    body += call_band()
    return subpage("learning", "<span class=\"nb\">읽기 · 학습</span>", "읽기 · 쓰기 · 수학이 유난히 힘든 아이, 느린 학습자를 위한 인지치료입니다.", body, kicker="인지치료", shape="a")

def aba():
    body = intro("행동 · 조기교실 — ABA", "<span class=\"nb\">어릴수록,</span> <span class=\"nb\">작은 단계로 나누어</span>",
        "<p><b>ABA(응용행동분석)</b>는 행동의 원리를 이용해 아이의 발달을 돕는 교육 방법입니다. 아이가 어떤 행동을 하는지 관찰하고, 환경을 조정하고, 적절한 행동을 강화합니다.</p><p><b>조기교실</b>은 어린 발달지연 아동이 기초 발달 능력을 배우도록 돕는 프로그램입니다. 이름을 부르면 돌아보기, 눈 맞추기, 요구 표현하기, 간단한 지시 따르기부터 시작합니다.</p>",
        "g-aba-a", "매트 위에서 아이가 나무 모양 끼우기를 하고, 선생님이 다음 조각을 건네는 모습", "", [("대상", "자폐스펙트럼 · 발달지연, 의사소통 · 상호작용이 어려운 어린 아동"), ("관련 자격", "원장 — 응용행동분석사(ABA) 1급 (한국인지행동심리학회)"), ("운영", "반 구성과 시간은 전화로 문의해 주세요")])
    body += who("<span class=\"nb\">이런 아이가</span> <span class=\"nb\">참여합니다</span>", ["이름을 불러도 잘 돌아보지 않는다", "눈 맞춤이 어렵다", "의사소통 발달이 느리다", "간단한 지시를 따르기 어렵다", "또래와 함께 활동하기 어렵다", "영유아 건강검진에서 발달이 느리다는 평가를 받았다"])
    body += sec(head("배우는 것", "<span class=\"nb\">네 영역의 기초를</span> <span class=\"nb\">단계로 배웁니다</span>") + cards([
        ("의사소통", dots(["요구 표현하기", "낱말 사용하기", "의사소통 시도 늘리기"])), ("사회성", dots(["눈 맞추기", "이름에 반응하기", "또래와 함께 활동하기"])),
        ("인지", dots(["색깔 구분", "모양 맞추기", "간단한 문제 해결"])), ("생활 기술", dots(["정리하기", "차례 기다리기", "간단한 규칙 따르기"]))]))
    body += sec(head("수업의 특징", "<span class=\"nb\">일반 수업과</span> <span class=\"nb\">다른 네 가지</span>") + steps([
        ("개별화", "아이의 발달 수준을 평가한 뒤 아이마다 목표를 정합니다."), ("작은 단계", "어려운 기술도 작은 단계로 나누어 배웁니다."), ("반복", "새 기술을 익히도록 충분히 되풀이합니다."), ("긍정적인 강화", "바람직한 행동이 나오면 칭찬 · 놀이 · 좋아하는 활동으로 이어 줍니다.")]), "sec-soft")
    body += sec(duo(f'{tag("왜 일찍인가")}<h2><span class="nb">발달이 걱정된다면</span> <span class="nb">되도록 이른 시기에</span></h2><div class="prose"><p>영유아기는 운동 · 언어 · 사회성 · 인지가 함께 자라는 시기입니다. 영유아 건강검진에서 늦다는 항목이 있다면 그 항목을 더 평가받아 보는 것이 좋습니다.</p><p>발달지연은 일찍 발견해 정확히 진단받고, 지켜보며 계획을 고쳐 가는 것이 중요합니다.</p></div>',
        f'<div class="callout"><h3>집에서 함께해 주세요</h3><p>배운 기술은 연구소에서만이 아니라 집에서도 함께 연습할 때 자리 잡습니다.</p>{dots(["아이가 요구를 표현하면 바로 반응해 주기", "눈 맞춤을 시도하면 칭찬해 주기", "차례 기다리기를 연습하기"])}</div>') + HOSP)
    body += call_band()
    return subpage("aba", "<span class=\"nb\">행동 · 조기교실</span>", "발달이 느린 어린 아이가 기초 발달 능력을 작은 단계로 배웁니다.", body, kicker="ABA", shape="b")

def arts():
    body = sec(duo(f'{tag("음악치료")}<h2><span class="nb">소리로</span> <span class="nb">주고받습니다</span></h2><div class="prose"><p>음악치료실에는 피아노와 기타가 있습니다. 음악치료 석사 과정을 마친 음악재활사 두 명이 수업을 맡습니다.</p></div>{kv([("담당", "음악재활사 2명 — 임상 경력 20년 · 12년"), ("자격", "음악치료사 1급 · 음악중재전문가 · 인지행동지도사 1급 (1명)"), VOUCH], "slim")}',
        figure("g-music-a", "피아노 건반 위에 선생님과 아이의 손이 나란히 놓인 모습", "", sizes="(max-width: 760px) 100vw, 600px")))
    body += sec(duo(figure("g-art-a", "아이가 크레파스로 해와 꽃, 집을 그리고 선생님이 크레파스를 건네는 모습", "", sizes="(max-width: 760px) 100vw, 600px"),
        f'{tag("미술치료")}<h2><span class="nb">그림으로</span> <span class="nb">표현합니다</span></h2><div class="prose"><p>미술치료실 벽에는 아이들의 그림이 걸려 있습니다. 회화 · 공예를 전공한 미술재활사 두 명이 수업을 맡습니다.</p></div>{kv([("담당", "미술재활사 2명 — 임상 경력 각 13년"), ("자격", "미술심리지도사 1급 · 컬러상담사 1급 · 특수아미술실기지도사"), VOUCH], "slim")}', "rev"), "sec-soft")
    body += sec(head("함께 받는 수업", "<span class=\"nb\">언어 · 인지와</span> <span class=\"nb\">함께 계획합니다</span>", "연구소는 언어 · 인지 · 미술 · 음악 영역을 함께 운영합니다. 어떤 영역부터 시작할지는 방문 상담에서 아이의 지금 모습을 보고 정합니다.") + note("음악 · 미술 수업의 구체적인 내용과 가능한 시간은 전화로 문의해 주세요."))
    body += call_band()
    return subpage("arts", "<span class=\"nb\">음악 · 미술</span>", "소리와 그림으로 표현을 넓히는 음악치료 · 미술치료입니다.", body, kicker="음악치료 · 미술치료", shape="a")

def group():
    body = sec(duo(f'{tag("그룹 활동")}<h2><span class="nb">또래와 함께,</span> <span class="nb">시기마다 엽니다</span></h2><div class="prose"><p>그룹 활동은 상시 운영이 아니라 시기에 따라 모집합니다. 아래는 그동안 열었던 프로그램의 기록입니다. 지금 모집하는지는 전화로 확인해 주세요.</p></div>', figure("g-group-a", "둥근 책상에 둘러앉은 아이들이 함께 나무 블록을 쌓는 모습", "", sizes="(max-width: 760px) 100vw, 600px"))) + sec('<div class="recs">' + "".join(f'<article class="rec rv"><p class="rec-when">{w}</p><h3>{t}</h3><p>{d}</p>{kv(r, "slim")}</article>' for w, t, d, r in [
        ("2026년 여름방학", "PECS · AAC 4주 특별활동", "팥빙수 · 감자튀김 · 쿠키 만들기, 클레이, 에코백 만들기와 지역사회 활동. 그림 카드와 의사소통 판으로 직접 고르고 표현하는 경험을 합니다.", [("대상", "발달장애 청소년 · 성인"), ("구성", "4 ~ 5명 소그룹"), ("진행", "주 1회 100분, 4주")]),
        ("2025년 1 ~ 2월", "초등학교 입학 준비반", "기초 생활 습관, 교실에서 지켜야 하는 안전 규칙, 바르고 고운 말로 나를 표현하고 친구 사귀기, 공부 습관을 익힙니다.", [("대상", "초등학교 입학을 앞둔 어린이"), ("구성", "4 ~ 5명"), ("진행", "주 1회 2시간, 2달")]),
        ("2020년 2월부터", "사회성 그룹", "친구들과 어울리기 어렵거나, 집단에서 지시 따르기 · 규칙 지키기가 어렵거나, 자신감이 부족해 의사 표현이 어려운 아이를 위한 수업입니다. 그룹 안의 여러 상황에서 알맞은 말하기를 배워 또래 관계의 성공 경험을 쌓습니다.", [("대상", "취학 전 · 초등 저학년 · 초등 고학년"), ("구성", "3 ~ 5명"), ("진행", "주 1회")]),
        ("2020년 2월", "부모교육 — 입학 적응과 가족 지원", "현직 특수교사를 모셔 입학 전 아이가 갖출 것, 부모의 준비, 교육과정을 설명하고 질문을 받았습니다. 연구소에 다니지 않는 보호자도 신청할 수 있었습니다.", [("대상", "입학을 앞두었거나 학교 적응이 어려운 특수교육대상 아동의 보호자")]),
    ]) + "</div>", "sec-recs")
    body += sec(head("참여 방법", "<span class=\"nb\">전화 상담 뒤</span> <span class=\"nb\">그룹으로 이어집니다</span>") + steps([("전화 문의", "지금 모집 중인 그룹이 있는지 확인합니다."), ("예약 상담", "처음 오시는 경우 예약 상담을 먼저 합니다."), ("그룹 연결", "나이와 특성에 맞는 그룹으로 연결합니다.")], "steps-3"), "sec-soft")
    body += call_band("지금 모집하는 그룹이 있는지 물어보세요", "그룹 활동은 시기마다 다릅니다. 전화로 확인해 주세요.")
    return subpage("group", "<span class=\"nb\">그룹 활동</span>", "사회성 그룹, 학교 준비반, 방학 특별활동처럼 또래와 함께하는 프로그램입니다.", body, kicker="시기별 모집", shape="b")

def pages(): return [("speech", speech()), ("aac", aac()), ("learning", learning()), ("aba", aba()), ("arts", arts()), ("group", group())]
